+func wantShellDefinitions(t *testing.T, tl *tools.Tools, names []string) []any {
+	t.Helper()
+	want := make([]any, len(names))
+	for i, name := range names {
+		var def map[string]any
+		var ok bool
+		if name == "shell" {
+			def, ok = tl.Definition(name)
+		} else {
+			def, ok = tools.Definition(name)
+		}
+		if !ok {
+			t.Fatalf("no definition for %q", name)
+		}
+		want[i] = def
+	}
+	return want
+}
+
+func TestShellDefinitionsUsesSuppliedShellDefinition(t *testing.T) {
+	tl := &tools.Tools{}
+	names := []string{"read_file", "shell", "list_files", "search_text"}
+	want := wantShellDefinitions(t, tl, names)
+	got := ShellDefinitions(tl, names)
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("ShellDefinitions(%v) = %v, want %v", names, got, want)
+	}
+}
+
+func TestShellDefinitionsWithoutShellKeepsRequestedOrder(t *testing.T) {
+	names := []string{"search_text", "read_file", "list_files"}
+	want := wantShellDefinitions(t, nil, names)
+	got := ShellDefinitions(nil, names)
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("ShellDefinitions(%v) = %v, want %v", names, got, want)
+	}
+}

